(()=>{const runtimeVersion=new URL(document.currentScript?.src||location.href,location.href).searchParams.get('v')||'0.121.1';let attempts=0;const status=document.createElement('div');status.setAttribute('role','status');status.className='note';status.textContent='Connecting to planetary command…';document.getElementById('page-overview')?.prepend(status);function load(){attempts++;const script=document.createElement('script');script.src='/game-runtime.js?v='+encodeURIComponent(runtimeVersion)+(attempts>1?'&retry='+attempts:'');script.onload=()=>{if(window.starfallGameReady){status.remove();window.starfallThemeReadiness?.runtimeReady();}else{window.starfallThemeReadiness?.failed('Command could not initialise. Open the error log for details.');status.textContent='Command could not initialise. Open the error log for details.';const button=document.createElement('button');button.className='btn';button.textContent='RELOAD COMMAND';button.onclick=()=>location.reload();status.append(button);}};script.onerror=()=>{script.remove();if(attempts<3){status.textContent='Reconnecting to planetary command…';setTimeout(load,500*attempts);}else{window.starfallThemeReadiness?.failed('Command files could not load. Your saved round has been retained.');status.textContent='Command files could not load. Your saved round has been retained.';const button=document.createElement('button');button.className='btn';button.textContent='RETRY CONNECTION';button.onclick=()=>{attempts=0;status.replaceChildren();load();};status.append(button);}};document.body.append(script);}load();})();
